from pathlib import Path
import html
ROOT=Path(__file__).resolve().parents[1]
A='../../assets/'
def write(path,text):
 p=ROOT/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text,encoding='utf-8')
def img(name,alt,cls='',eager=False):return f'<img class="{cls}" src="{A}images/{name}.webp" alt="{alt}" width="1440" height="960" loading="{"eager" if eager else "lazy"}" decoding="async">'
def btn(t,u,second=False):return f'<a class="button{" secondary" if second else ""}" href="{u}">{t}</a>'
def dl(rows):return '<dl class="data-list">'+''.join(f'<div><dt>{a}</dt><dd>{b}</dd></div>' for a,b in rows)+'</dl>'
def faq(rows):return '<div class="faq">'+''.join(f'<details><summary>{a}</summary><p>{b}</p></details>' for a,b in rows)+'</div>'
def steps(rows):return '<ol class="steps">'+''.join(f'<li><h3>{a}</h3><p>{b}</p></li>' for a,b in rows)+'</ol>'
def section(head,body,eyebrow='',cls='',id=''):return f'<section class="section {cls}"'+(f' id="{id}"' if id else '')+f'><div class="wrap"><div class="section-head"><p class="eyebrow">{eyebrow}</p><h2>{head}</h2></div>{body}</div></section>'
def pagehead(title,lead,english):return f'<div class="page-head"><div class="wrap"><div class="breadcrumbs"><a href="index.html">ホーム</a> / {title}</div><p class="eyebrow">{english}</p><h1>{title}</h1><p class="lead">{lead}</p></div></div>'
def band(title,text,label,url):return f'<section class="band"><div class="wrap"><div><h2>{title}</h2><p>{text}</p></div>{btn(label,url)}</div></section>'
def form(subjects,verb='お問い合わせ',extra='',label='ご相談内容'):
 opts=''.join(f'<option>{x}</option>' for x in subjects)
 return f'''<div class="demo-note"><strong>入力体験用のフォームです。</strong><br>内容は送信・保存されません。実際の個人情報を入力せず、架空の内容でお試しください。{verb}は成立しません。</div><form class="demo-form">
 <label class="field"><span>ご用件 <b class="required">必須</b></span><select name="subject" data-summary="ご用件" required><option value="">選択してください</option>{opts}</select></label>{extra}
 <div class="two"><label class="field"><span>お名前 <b class="required">必須</b></span><input name="name" autocomplete="off" data-summary="お名前" required maxlength="60"></label><label class="field"><span>メールアドレス <b class="required">必須</b></span><input name="email" type="email" autocomplete="off" required maxlength="160" aria-describedby="email-help"><small id="email-help">試用には sample@example.com をお使いください。</small></label></div>
 <label class="field"><span>{label}</span><textarea name="message" maxlength="1500" data-summary="内容"></textarea></label><label class="check"><input type="checkbox" required><span>制作サンプルであり、入力内容が送信されないことを確認しました。</span></label><button type="submit" class="button">入力内容を確認する</button><div class="form-result" role="status" tabindex="-1" hidden></div><noscript><p>入力確認にはJavaScriptが必要です。実際の送信は行いません。</p></noscript></form>'''
def shell(slug,brand,en,nav,current,title,desc,body,sticky='',bodyclass=''):
 links=''.join(f'<a href="{u}"'+(' aria-current="page"' if u==current else '')+(' class="nav-cta"' if i==len(nav)-1 else '')+f'>{t}</a>' for i,(t,u) in enumerate(nav))
 foot=''.join(f'<a href="{u}">{t}</a>' for t,u in nav)
 s=f'''<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>{title}｜{brand}（制作サンプル）</title><meta name="description" content="{desc} 架空の事業者を想定した制作サンプルです。"><link rel="stylesheet" href="{A}base.css"><link rel="stylesheet" href="style.css"><script src="{A}site.js" defer></script></head><body class="{bodyclass}{' has-sticky' if sticky else ''}"><a class="skip" href="#main">本文へ移動</a><div class="sample-bar"><span>制作サンプル / 架空の事業者です。予約・送信はできません。</span><a href="../../index.html#works">ポートフォリオへ戻る</a></div><header class="site-header"><div class="wrap header-inner"><a class="brand" href="index.html">{brand}<small>{en}</small></a><button class="menu-toggle" aria-expanded="false" aria-controls="site-nav">メニュー</button><nav class="nav" id="site-nav" aria-label="メインメニュー">{links}</nav></div></header><main id="main">{body}</main><footer class="site-footer"><div class="wrap"><div class="footer-main"><div class="brand">{brand}<small>{en}</small></div><nav aria-label="フッター">{foot}</nav></div><div class="footer-note"><p>このサイトはMorisaki Webの制作サンプルです。名称・サービス・料金・営業情報は架空の設定です。写真はイメージ素材であり、実際の店舗・施工・設備・実績を示すものではありません。</p><p><a href="../../index.html#works">制作サンプル一覧へ</a>　/　<a href="../../credits.html">写真の出典</a>　 © {en} / Sample website</p></div></div></footer>{sticky}</body></html>'''
 write(f'works/{slug}/{current}',s)
# 02 / Seitai: a calm, practical first-visit page.
slug='seitai';nav=[('初めての方へ','#first'),('料金','#menu'),('営業案内','#access'),('初回予約','#reserve')]
body=f'''<section class="clinic-hero"><div class="wrap clinic-grid"><div class="clinic-copy"><p class="eyebrow">肩・腰の負担が気になる方へ / 予約制</p><h1>まずは、今の体のことを<br>話す時間から。</h1><p>仕事中の肩の重さ、立ち上がるときの腰の違和感。<br>いつ、どんな動きで気になるのかをうかがい、<br class="desktop">無理のない範囲で体を動かしながら確認します。</p><div class="button-row">{btn('初回の予約方法を見る','#reserve')}</div><p class="small muted">初回 約60分 / 6,000円（税込）</p></div><figure>{img('seitai','施術ベッドと落ち着いた室内のイメージ',eager=True)}<figcaption>施術室のイメージ写真</figcaption></figure></div></section><div class="clinic-info"><div class="wrap"><span>着替えの用意あり</span><span>施術前に内容と料金を説明</span><span>回数券の販売なし</span></div></div>'''
body+=section('初めての方へ',f'''<div class="two"><div><p class="lead">「うまく説明できない」ままでも<br>お越しいただけます。</p><p class="muted">姿勢や仕事中の動き、睡眠など、普段の生活についてお聞きします。施術を受けるかどうかは、説明を聞いてからお決めください。</p><div class="clinic-notice"><h3>ご来院前に</h3><p>当院の整体は医療行為ではありません。診断や治療、効果を保証するものではありません。体調に不安がある場合や通院中の方は、事前に医療機関へご相談ください。</p></div></div>{steps([('お話をうかがう','気になる場所や動作、これまでの経過を確認します。'),('動きを確認し、施術を説明','無理なく動かせる範囲を一緒に確認。触れる箇所や施術内容を先にお伝えします。'),('施術と日常の振り返り','強さを確認しながら進め、日常で負担になりやすい動きを振り返ります。')])}</div>''','FIRST VISIT',id='first')
body+=section('料金は、施術前にお伝えします。','''<div class="clinic-prices"><article><p>初めての方</p><h3>初回カウンセリング＋整体</h3><div class="price">6,000<span>円 / 税込</span></div><p>約60分（お話・動きの確認・施術を含む）</p></article><article><p>2回目以降</p><h3>整体</h3><div class="price">5,000<span>円 / 税込</span></div><p>約40分（当日の状態確認を含む）</p></article></div><p class="small muted">健康保険は適用されません。入会金・指名料はありません。お支払いは施術後です。すべてサンプル用の料金設定です。</p>''','MENU & PRICE',cls='clinic-soft',id='menu')
body+=section('予約前によくいただくご質問',faq([('どんな服装で行けばよいですか？','締め付けの少ない、動きやすい服装をおすすめしています。お着替えをご希望の場合は予約時にお知らせください。'),('痛い施術が苦手です。','力の強さはその都度確認します。痛みや不安を感じたら、途中でも遠慮なくお伝えください。'),('通う回数は決まっていますか？','一律の来院回数は設定していません。状態やご希望を確認したうえでご案内します。'),('予約の変更や遅刻はどうすればよいですか？','分かった時点でご連絡ください。到着時刻によっては施術時間の短縮や日時変更をご相談する場合があります。')]),'FAQ')
body+=section('営業・アクセス案内',f'''<div class="two"><div>{dl([('受付時間','10:00〜19:00（最終受付18:00）'),('休院日','水曜日・日曜日'),('来院方法','完全予約制。予約確定時に来院方法をご案内します。'),('所在地','架空の整体院のため、実在の住所・地図は掲載していません。')])}</div><div class="clinic-hours"><h3>受付カレンダー</h3><table class="data-table"><thead><tr><th>時間</th><th>月・火・木・金</th><th>土</th></tr></thead><tbody><tr><th>10:00–13:00</th><td>受付</td><td>受付</td></tr><tr><th>14:00–19:00</th><td>受付</td><td>受付</td></tr></tbody></table><p class="small">水・日休院 / 空き状況は予約時にご確認ください。</p></div></div>''','INFORMATION',id='access')
extra='<label class="field"><span>希望する連絡方法</span><select name="channel" data-summary="連絡方法"><option value="web">WEB予約</option><option value="line">LINE予約</option><option value="phone">電話予約</option></select></label><label class="field"><span>ご希望日時</span><input name="date" type="datetime-local" data-summary="希望日時"></label>'
body+=section('ご都合のよい方法で、ご予約を。',f'''<p>通常の予約では、ご希望日時をうかがい、空き状況を確認して折り返します。<br>このサンプルでは、下のフォームで予約導線を体験できます。</p><div class="channel-row"><a href="#booking" data-demo-channel="web">WEB予約 <small>入力デモへ</small></a><a href="#booking" data-demo-channel="line">LINE予約 <small>案内デモへ</small></a><a href="#booking" data-demo-channel="phone">電話予約 <small>案内デモへ</small></a></div><div id="booking">{form(['初回カウンセリング＋整体','2回目以降の整体','来院前の質問'],'予約',extra,'気になっていること（架空の内容でお試しください）')}</div>''','RESERVATION',cls='clinic-soft',id='reserve')
shell(slug,'みどり整体院','MIDORI BODY CARE',nav,'index.html','初めての方へ・料金と予約','初回の流れ、料金、営業案内がわかる整体院サイト。',body,sticky='<div class="sticky-mobile">'+btn('料金を見る','#menu',True)+btn('初回予約','#reserve')+'</div>')
write('works/seitai/style.css',''' :root{--ink:#243f36;--sub:#556b62;--paper:#fff;--soft:#eef4f0;--line:#cedbd3;--accent:#28634f}.brand{font-family:'Yu Mincho',serif;font-size:25px}.clinic-hero{padding:55px 0 65px;background:#f6f8f5}.clinic-grid{display:grid;grid-template-columns:1.2fr 1fr;align-items:center;gap:40px}.clinic-copy h1{font-family:'Yu Mincho',serif;font-size:clamp(2rem,3.1vw,3rem);line-height:1.75;letter-spacing:.04em}.clinic-copy>p{margin-top:22px;font-size:16px}.clinic-copy>.eyebrow{margin-top:0;font-size:13px}.clinic-grid figure img{height:470px;object-fit:cover;border-radius:140px 4px 4px 4px}.clinic-grid figcaption{font-size:12px;text-align:right;margin-top:10px}.clinic-info{border-bottom:1px solid var(--line)}.clinic-info .wrap{display:flex;justify-content:space-between;gap:20px;padding:22px 0;font-size:14px}.button,.nav .nav-cta{border-radius:5px}.clinic-soft{background:var(--soft)}.clinic-notice{border-top:1px solid var(--line);margin-top:30px;padding-top:25px;font-size:14px}.clinic-notice h3{font-size:16px;margin-bottom:8px}.clinic-prices{display:grid;grid-template-columns:1fr 1fr;gap:30px;margin-bottom:24px}.clinic-prices article{background:white;padding:36px}.clinic-prices h3{margin:15px 0}.price{font-family:Georgia,serif;font-size:44px;line-height:1.5;margin:15px 0}.price span{font-size:14px;margin-left:12px}.clinic-hours{padding:25px;background:var(--soft)}.clinic-hours h3{margin-bottom:20px}.clinic-hours .data-table th,.clinic-hours .data-table td{padding:15px 6px;font-size:13px}.channel-row{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin:35px 0}.channel-row a{padding:22px;text-decoration:none;background:white;border:1px solid var(--accent);font-weight:600}.channel-row small{display:block;font-size:13px;font-weight:400}.demo-form{max-width:none}.clinic-soft .demo-note{background:white}@media(max-width:760px){.clinic-grid{grid-template-columns:1fr;gap:25px}.clinic-hero{padding:32px 0}.clinic-copy h1{font-size:27px}.clinic-copy p br{display:none}.clinic-grid figure img{height:270px;border-radius:70px 3px 3px 3px}.clinic-info .wrap{flex-wrap:wrap;justify-content:flex-start;gap:8px 20px;font-size:12px}.clinic-prices{grid-template-columns:1fr}.clinic-prices article{padding:25px}.channel-row{gap:8px}.channel-row a{padding:16px 10px;font-size:14px}.channel-row small{font-size:11px}.clinic-hours{padding:18px}}''')
